WITH cleaned AS (SELECT *, COALESCE(email, 'Unknown') AS email_filled FROM employees WHERE hire_date >= DATE '2023-12-03' AND manager_id IS NOT NULL) SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, email_filled, ROW_NUMBER() OVER (PARTITION BY job_title, dept_id ORDER BY hire_date, id) AS event_seq, FIRST_VALUE(job_title, TRUE) OVER (ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title FROM cleaned;
